def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    segments = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2-r1, c2-c1
            if abs(dr) == abs(dc) and dr != 0:
                sr = 1 if dr > 0 else -1
                sc = 1 if dc > 0 else -1
                cells = [(r1+k*sr, c1+k*sc) for k in range(abs(dr)+1)]
                segments.append((cells, sr == sc))
                for r, c in cells:
                    if grid[r][c] != 6:
                        out[r][c] = 1
    for cells, slope_positive in segments:
        cellset = set(cells)
        for r0, c0 in sixes:
            if (r0, c0) not in cellset:
                continue
            # A marker on the 1 diagonal sends a 6 diagonal across the grid.
            for r in range(h):
                c = (r0 + c0 - r) if slope_positive else (c0 + r - r0)
                if 0 <= c < w and out[r][c] != 1:
                    out[r][c] = 6
    return out
